src={f:open(f,encoding='utf8',errors='ignore').read() for f in files}
declre=re.compile(r'^func\s+(?:\([^)]*\)\s*)?([A-Za-z_]\w*)\s*[\(\[]',re.M)
internal_syms=collections.defaultdict(list)
for f,t in src.items():
