            line=t[line_start:t.find('\n',m.start())]
            if line.lstrip().startswith('func '): continue
            n+=1
    counts[sym]=(n,locs)
for sym,(n,locs) in sorted(counts.items(),key=lambda x:-x[1][0])[:25]:
    print(n,sym,locs[:3])
